<?php
namespace App\Services;use App\Models\{Committee,CommitteeMeeting};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class CommitteeMeetingService{public function __construct(private CommitteeOperationService $operations,private CommitteeQuorumService $quorum){}public function create(Committee $committee,array $data,int $userId):CommitteeMeeting{$this->operations->ensureActive($committee);$formation=$committee->latestFinalFormation;$president=$formation->period->roles()->where('role','president')->whereDate('starts_at','<=',$data['meeting_date'])->whereDate('ends_at','>=',$data['meeting_date'])->latest()->first();$secretary=$formation->period->roles()->where('role','secretary')->whereDate('starts_at','<=',$data['meeting_date'])->whereDate('ends_at','>=',$data['meeting_date'])->latest()->first();if(!$president||!$secretary)throw ValidationException::withMessages(['roles'=>'No existen Presidente y Secretario vigentes para la fecha.']);$meeting=$committee->meetings()->create(array_merge($data,['committee_period_id'=>$formation->committee_period_id,'president_member_id'=>$president->committee_member_id,'secretary_member_id'=>$secretary->committee_member_id,'status'=>'scheduled','created_by'=>$userId,'updated_by'=>$userId]));foreach($formation->period->members()->where('status','active')->get() as $member)$meeting->attendees()->create(['committee_member_id'=>$member->id,'employee_id'=>$member->employee_id,'attendance_status'=>'absent']);$suggested=['Verificación de asistencia','Verificación del quórum','Aprobación del orden del día','Revisión del acta anterior','Seguimiento de compromisos','Temas programados','Proposiciones y recomendaciones','Nuevos compromisos','Cierre'];foreach($suggested as $i=>$title)$meeting->agendaItems()->create(['sort_order'=>$i+1,'title'=>$title,'type'=>'standard','status'=>'pending']);if($meeting->schedule_item_id)$meeting->scheduleItem()->update(['status'=>'in_progress']);$this->operations->audit($committee,'meeting_called',$meeting,$userId);return$meeting;}public function updateAttendance(CommitteeMeeting $meeting,array $rows,int $userId):array{abort_if(in_array($meeting->status,['closed','cancelled']),422,'La reunión ya no admite asistencia.');foreach($rows as $row)$meeting->attendees()->whereKey($row['id'])->update(['attendance_status'=>$row['attendance_status'],'arrival_time'=>$row['arrival_time']??null,'observation'=>$row['observation']??null,'replaces_member_id'=>$row['replaces_member_id']??null]);$meeting->load(['attendees.member','period']);$result=$this->quorum->calculate($meeting);$meeting->update(['quorum_required'=>$result['required'],'quorum_present'=>$result['present'],'has_quorum'=>$result['has_quorum'],'updated_by'=>$userId]);$this->operations->audit($meeting->committee,'quorum_verified',$meeting,$userId,$result);return$result;}public function start(CommitteeMeeting $meeting,int $userId):void{$this->operations->ensureActive($meeting->committee);$meeting->load(['attendees.member','period']);$result=$this->quorum->calculate($meeting);$meeting->update(['quorum_required'=>$result['required'],'quorum_present'=>$result['present'],'has_quorum'=>$result['has_quorum'],'status'=>$result['has_quorum']?'in_progress':'failed_quorum','updated_by'=>$userId]);$this->operations->audit($meeting->committee,$result['has_quorum']?'meeting_started':'meeting_failed_quorum',$meeting,$userId,$result);}public function complete(CommitteeMeeting $meeting,array $data,int $userId):void{if($meeting->status!=='in_progress'||!$meeting->has_quorum)throw ValidationException::withMessages(['meeting'=>'Solo puede cerrarse una reunión iniciada con quórum.']);DB::transaction(function()use($meeting,$data,$userId){foreach($data['agenda']??[] as $row)$meeting->agendaItems()->whereKey($row['id'])->update(['status'=>$row['status'],'development'=>$row['development']??null,'conclusions'=>$row['conclusions']??null,'observations'=>$row['observations']??null]);$meeting->update(['status'=>'minutes_draft','end_time'=>$data['end_time'],'updated_by'=>$userId]);if($meeting->scheduleItem)$meeting->scheduleItem->update(['status'=>'completed','updated_by'=>$userId]);$this->operations->audit($meeting->committee,'meeting_completed',$meeting,$userId);});}}
